-- 5. Gói thành viên -------------------------------------------------------
SET IDENTITY_INSERT dbo.MembershipPackage ON;
INSERT dbo.MembershipPackage (Id, Name, Price, DurationMonths, Benefits, IsActive, CreatedAt) VALUES (1, N'Gói Trải Nghiệm - 1 Tháng', 350000, 1, N'["Sử dụng toàn bộ trang thiết bị Gym và khu Cardio","Tủ đồ cá nhân thông minh trong giờ tập","Khu vực tắm nóng lạnh và phòng thay đồ"]', 1, DATEADD(MONTH, -18, @now));
INSERT dbo.MembershipPackage (Id, Name, Price, DurationMonths, Benefits, IsActive, CreatedAt) VALUES (2, N'Gói Yoga & Fitness - 1 Tháng', 450000, 1, N'["Toàn quyền tập luyện Gym và các lớp Yoga","Tham gia tối đa 8 lớp Yoga hoặc Pilates mỗi tháng","Thảm và dụng cụ hỗ trợ do trung tâm cung cấp","Tư vấn dinh dưỡng cơ bản 1 lần mỗi tháng"]', 1, DATEADD(MONTH, -18, @now));
INSERT dbo.MembershipPackage (Id, Name, Price, DurationMonths, Benefits, IsActive, CreatedAt) VALUES (3, N'Gói Năng Động - 3 Tháng', 950000, 3, N'["Tập luyện không giới hạn mọi khung giờ","Đo chỉ số cơ thể InBody định kỳ hàng tháng","1 buổi định hướng tập luyện cùng huấn luyện viên","Tham gia các lớp Zumba, Cardio HIIT và Cầu lông"]', 1, DATEADD(MONTH, -18, @now));
INSERT dbo.MembershipPackage (Id, Name, Price, DurationMonths, Benefits, IsActive, CreatedAt) VALUES (4, N'Gói Bơi Lội & Gym - 3 Tháng', 1250000, 3, N'["Sử dụng hồ bơi bốn mùa nước ấm và khu Gym","2 buổi kiểm tra thể lực chuyên sâu","Tủ gửi đồ cá nhân cao cấp","Giảm 10% dịch vụ xông hơi và massage thể thao"]', 1, DATEADD(MONTH, -18, @now));
INSERT dbo.MembershipPackage (Id, Name, Price, DurationMonths, Benefits, IsActive, CreatedAt) VALUES (5, N'Gói Boxing Chuyên Sâu - 3 Tháng', 1500000, 3, N'["Tập luyện Boxing và Kickfit cùng HLV chuyên nghiệp","Trang bị găng tay và bảo hộ trong suốt khóa học","2 buổi đối luyện có ghi hình phân tích kỹ thuật"]', 1, DATEADD(MONTH, -18, @now));
INSERT dbo.MembershipPackage (Id, Name, Price, DurationMonths, Benefits, IsActive, CreatedAt) VALUES (6, N'Gói Hội Viên Vàng - 12 Tháng', 3200000, 12, N'["Tập luyện không giới hạn toàn hệ thống trong 1 năm","Tặng 3 buổi tập riêng 1 kèm 1 cùng huấn luyện viên","Đo InBody và tư vấn dinh dưỡng hàng tháng","Ưu tiên giữ chỗ các lớp học đông hội viên","Miễn phí 2 lần bảo lưu gói tập trong năm"]', 1, DATEADD(MONTH, -18, @now));
INSERT dbo.MembershipPackage (Id, Name, Price, DurationMonths, Benefits, IsActive, CreatedAt) VALUES (7, N'Gói VIP Kim Cương - 12 Tháng', 4800000, 12, N'["Toàn quyền Gym, Hồ bơi, Xông hơi, Yoga và Boxing","Tặng 6 buổi huấn luyện viên cá nhân (PT)","Tủ đồ VIP cố định riêng cả năm","Khăn tập và nước uống thể thao miễn phí mỗi buổi","Dẫn theo 1 khách mời miễn phí 2 lần mỗi tháng","Hỗ trợ đặt lịch ưu tiên qua tổng đài riêng"]', 1, DATEADD(MONTH, -18, @now));
INSERT dbo.MembershipPackage (Id, Name, Price, DurationMonths, Benefits, IsActive, CreatedAt) VALUES (8, N'Gói Dancesport - 1 Tháng', 500000, 1, N'["Lớp khiêu vũ thể thao cơ bản theo cặp","Tạm ngừng mở bán trong quý này"]', 0, DATEADD(MONTH, -18, @now));
