INSERT dbo.Class (Id, DisciplineId, Name, Description, Capacity, Status, CreatedAt, CreatedBy) VALUES (1, 1, N'Gym Nền Tảng Buổi Sáng', N'Lớp hướng dẫn kỹ thuật tạ cơ bản, phù hợp hội viên mới bắt đầu.', 20, 'OPEN', DATEADD(MONTH, -6, @now), 'acc-mgr-001');
INSERT dbo.Class (Id, DisciplineId, Name, Description, Capacity, Status, CreatedAt, CreatedBy) VALUES (2, 1, N'Gym Tăng Cơ Nâng Cao', N'Giáo án tăng cơ theo nhóm cơ, dành cho hội viên đã tập trên 6 tháng.', 16, 'OPEN', DATEADD(MONTH, -6, @now), 'acc-mgr-001');
INSERT dbo.Class (Id, DisciplineId, Name, Description, Capacity, Status, CreatedAt, CreatedBy) VALUES (3, 2, N'Yoga Buổi Sáng An Yên', N'Chuỗi Hatha nhẹ nhàng giúp khởi động cơ thể và điều hòa hơi thở.', 20, 'OPEN', DATEADD(MONTH, -6, @now), 'acc-mgr-001');
INSERT dbo.Class (Id, DisciplineId, Name, Description, Capacity, Status, CreatedAt, CreatedBy) VALUES (4, 2, N'Yoga Vinyasa Buổi Tối', N'Chuỗi động tác liên hoàn theo nhịp thở, tăng sức bền và độ dẻo.', 20, 'OPEN', DATEADD(MONTH, -6, @now), 'acc-mgr-001');
INSERT dbo.Class (Id, DisciplineId, Name, Description, Capacity, Status, CreatedAt, CreatedBy) VALUES (5, 3, N'Pilates Cơ Lõi', N'Bài tập thảm tập trung vào cơ lõi, cải thiện tư thế và giảm đau lưng.', 14, 'OPEN', DATEADD(MONTH, -6, @now), 'acc-mgr-001');
INSERT dbo.Class (Id, DisciplineId, Name, Description, Capacity, Status, CreatedAt, CreatedBy) VALUES (6, 4, N'Boxing Căn Bản', N'Học tấn, di chuyển và các đòn tay cơ bản của quyền Anh.', 16, 'OPEN', DATEADD(MONTH, -6, @now), 'acc-mgr-001');
