INSERT dbo.MemberSubscription (Id, MemberId, PackageId, PackageName, PackagePrice, DurationMonths, Benefits, StartDate, EndDate, Kind, Status, CreatedAt, IsSuspended) VALUES (3, 'acc-mem-002', 3, N'Gói Năng Động - 3 Tháng', 950000, 3, N'["Tập luyện không giới hạn mọi khung giờ","Đo chỉ số cơ thể InBody định kỳ hàng tháng","1 buổi định hướng tập luyện cùng huấn luyện viên","Tham gia các lớp Zumba, Cardio HIIT và Cầu lông"]', DATEADD(DAY, 0, DATEADD(MONTH, -1, @today)), DATEADD(DAY, -1, DATEADD(MONTH, 3, DATEADD(DAY, 0, DATEADD(MONTH, -1, @today)))), 'REGISTER', 'CONFIRMED', DATEADD(MONTH, -1, @now), 0);
